// parent[v] 是父节点；size[r] 只在根 r 上记录集合大小；components 是当前集合数。find 保持集合划分不变，unite 只在两个根不同的时候减少集合数。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

// 顶点编号 [0,n)，路径压缩 + 按集合大小合并。
struct DSU {
    vector<int> parent, size;
    int components;
    explicit DSU(int n) : parent(n), size(n, 1), components(n) {
        // 初始每个点自成一个集合，父节点指向自己。
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int vertex) {
        // 先用 root 找到真正的根；vertex 暂时保留起点，供第二遍压缩。
        int root = vertex;
        // 沿父指针走到根，根满足 parent[root] == root。
        while (root != parent[root]) root = parent[root];
        while (vertex != root) {
            // 改写父指针前先记住原父亲，避免丢失还没压缩的那一段。
            int next = parent[vertex];
            // 把经过的点直接挂到根；下次查询就不用重复走这条长链。
            parent[vertex] = root;
            vertex = next;
        }
        return root;
    }
    // 根相同等价于两个点在同一集合。
    bool same(int a, int b) { return find(a) == find(b); }
    // 先找到根，只有根处的 size 才代表整个集合的大小。
    int component_size(int vertex) { return size[find(vertex)]; }
    bool unite(int a, int b) {
        // 合并的是整棵集合树，必须先把点转换成各自的根。
        a = find(a); b = find(b);
        // 已连通时不修改大小和集合数，也不重复计数。
        if (a == b) return false;
        // 让小树挂到大树，限制树高；交换根不改变两集合的内容。
        if (size[a] < size[b]) swap(a, b);
        // 让 b 所在集合并入 a；此后 b 不再是根。
        parent[b] = a;
        // 新根的大小等于两个旧集合大小之和。
        size[a] += size[b];
        // 一次成功合并恰好使集合数减一。
        --components;
        return true;
    }
};

templates.example:
// 最小调用示例：下列断言同时展示正常结果与边界约定。
int main() {
    DSU sets(5);
    sets.unite(0, 1); sets.unite(1, 2);
    assert(sets.same(0, 2) && sets.component_size(1) == 3);
    assert(!sets.unite(2, 0) && sets.components == 3);
}

