// graph[u] 存从 u 出发的边；edge.to/weight 是终点/非负权。distance[v] 是当前最短距离，parent[v] 记录取得这次距离的前驱；DIST_INF 表示不可达。最短距离必须小于 DIST_INF。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct WeightedEdge { int to; long long weight; };
constexpr long long DIST_INF = numeric_limits<long long>::max() / 4;
struct ShortestPaths {
    vector<long long> distance;
    vector<int> parent;
    vector<int> path_to(int target) const {
        // 不可达点没有路径；源点的路径只包含自己。
        if (distance[target] == DIST_INF) return {};
        vector<int> path;
        // 从终点沿前驱倒着走到源点，再反转得到正向路径。
        for (int v = target; v != -1; v = parent[v]) path.push_back(v);
        reverse(path.begin(), path.end());
        return path;
    }
};
ShortestPaths dijkstra(const vector<vector<WeightedEdge>>& graph, int source) {
    int n = graph.size();
    // 所有点先设不可达，前驱 -1 同时标记路径的结束。
    ShortestPaths result{vector<long long>(n, DIST_INF), vector<int>(n, -1)};
    // 小根堆优先处理当前距离最小的候选点。堆项存（距离，顶点）。
    priority_queue<pair<long long,int>, vector<pair<long long,int>>,
                   greater<pair<long long,int>>> pending;
    // 源点到自己距离为 0，这是唯一的初始确定信息。
    result.distance[source] = 0;
    pending.push({0, source});
    while (!pending.empty()) {
        // 弹出一份历史候选；同一顶点允许多次进堆。
        auto [current, vertex] = pending.top(); pending.pop();
        // 若它已被更短路径替代，就丢弃过期堆项，不再扩展邻边。
        if (current != result.distance[vertex]) continue;
        for (auto edge : graph[vertex]) {
            // Dijkstra 依赖非负权；有负边应选 Bellman–Ford。
            assert(edge.weight >= 0);
            // 先检查加法边界，避免距离溢出或与不可达标记混淆。
            if (edge.weight > DIST_INF - current) continue;
            // 尝试用“到 vertex 的路 + 当前边”抵达终点。
            long long candidate = current + edge.weight;
            // 松弛成功后同时更新距离和对应前驱。
            if (candidate >= result.distance[edge.to]) continue;
            // 松弛成功后同时更新距离和对应前驱。
            result.distance[edge.to] = candidate;
            result.parent[edge.to] = vertex;
            // 新候选入堆；无需在堆中查找或删除旧候选。
            pending.push({candidate, edge.to});
        }
    }
    return result;
}

templates.example:
// 最小调用示例：下列断言同时展示正常结果与边界约定。
int main() {
    vector<vector<WeightedEdge>> graph(4);
    graph[0] = {{1, 7}, {2, 2}}; graph[2] = {{1, 1}};
    auto result = dijkstra(graph, 0);
    assert(result.distance[1] == 3 && result.path_to(1) == vector<int>({0,2,1}));
    assert(result.path_to(3).empty());
}

