#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct Edge { int v; long long w; };
constexpr long long INF = numeric_limits<long long>::max() / 4;
struct SP {
    vector<long long> dis;
    vector<int> p;
    vector<int> path(int t) const {
        if (dis[t] == INF) return {};
        vector<int> path;
        for (int v = t; v != -1; v = p[v]) path.push_back(v);
        reverse(path.begin(), path.end());
        return path;
    }
};
SP dijkstra(const vector<vector<Edge>>& g, int s) {
    int n = g.size();
    SP res{vector<long long>(n, INF), vector<int>(n, -1)};
    priority_queue<pair<long long,int>, vector<pair<long long,int>>,
                   greater<pair<long long,int>>> q;
    res.dis[s] = 0;
    q.push({0, s});
    while (!q.empty()) {
        auto [du, u] = q.top(); q.pop();
        if (du != res.dis[u]) continue;
        for (auto e : g[u]) {
            assert(e.w >= 0);
            if (e.w > INF - du) continue;
            long long nd = du + e.w;
            if (nd >= res.dis[e.v]) continue;
            res.dis[e.v] = nd;
            res.p[e.v] = u;
            q.push({nd, e.v});
        }
    }
    return res;
}

