// 无向边 MSTEdge 记录 from/to 两端、weight 权重、id 原编号。result.weight 是最小生成森林总权重，edge_ids 是选中的原边编号；components>1 表示原图不连通。下面 DSU 的 parent/size/components 分别为父指针、根的集合大小和集合数。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

// 顶点编号 [0,n)，路径压缩 + 按集合大小合并。
struct DSU {
    vector<int> parent, size;
    int components;
    explicit DSU(int n) : parent(n), size(n, 1), components(n) {
        // 初始每个点是独立集合。
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int vertex) {
        // root 用来定位集合根，再从原 vertex 开始压缩路径。
        int root = vertex;
        while (root != parent[root]) root = parent[root];
        while (vertex != root) {
            // 改写父指针前保留旧父亲。
            int next = parent[vertex];
            // 路径压缩只缩短查找路径，不改变集合成员。
            parent[vertex] = root;
            vertex = next;
        }
        return root;
    }
    bool same(int a, int b) { return find(a) == find(b); }
    int component_size(int vertex) { return size[find(vertex)]; }
    bool unite(int a, int b) {
        // 先转换到根，合并才会作用于两个完整的连通块。
        a = find(a); b = find(b);
        // 同一连通块内再加边会形成环，应跳过。
        if (a == b) return false;
        // 按大小合并，让较小集合的根挂到较大集合。
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        // 只在新根处维护合并后的集合大小。
        size[a] += size[b];
        --components;
        return true;
    }
};

struct MSTEdge { int from, to; long long weight; int id; };
struct MSTResult {
    long long weight = 0;
    vector<int> edge_ids;
    int components = 0;
    bool connected() const { return components <= 1; }
};
MSTResult kruskal(int n, vector<MSTEdge> edges) {
    // 按权重从小到大尝试边；原编号只用于等权时稳定选边。
    sort(edges.begin(), edges.end(), [](const MSTEdge& a, const MSTEdge& b) {
        return tie(a.weight, a.id) < tie(b.weight, b.id);
    });
    // 并查集维护已选边形成的连通块。
    DSU sets(n);
    MSTResult result;
    for (const auto& edge : edges) {
        // 自环和已连通两端的边都不会进入生成森林。
        if (!sets.unite(edge.from, edge.to)) continue;
        // 成功连接两个块才累计权重，负权边也正常处理。
        result.weight += edge.weight;
        // 记录原编号，便于还原选边结果。
        result.edge_ids.push_back(edge.id);
        // n 个点已连通就可停止，生成树已有 n-1 条边。
        if (sets.components == 1) break;
    }
    // 保留最终连通块数；不能把不连通森林误报为生成树。
    result.components = sets.components;
    return result;
}

templates.example:
// 最小调用示例：下列断言同时展示正常结果与边界约定。
int main() {
    vector<MSTEdge> edges = {{0,1,3,0}, {1,2,-1,1}, {0,2,5,2}, {1,1,-9,3}};
    auto result = kruskal(3, edges);
    assert(result.connected() && result.weight == 2 && result.edge_ids.size() == 2);
    assert(!kruskal(4, edges).connected());
}

