// distance[v] 是从所有 sources 中任意一个点出发的最少边数；-1 表示不可达。parent[v] 是发现 v 的前驱，源点前驱为 -1。pending 按发现顺序处理点，天然按距离分层。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct BFSResult { vector<int> distance, parent; };
BFSResult bfs(const vector<vector<int>>& graph, const vector<int>& sources) {
    int n = graph.size();
    // 距离 -1 兼作“尚未发现”标记，因此每个点只会入队一次。
    BFSResult result{vector<int>(n, -1), vector<int>(n, -1)};
    queue<int> pending;
    // 多个源同时作为第 0 层，求的是离最近源的距离。
    for (int source : sources) {
        // 重复源只入队一次。
        if (result.distance[source] != -1) continue;
        result.distance[source] = 0; pending.push(source);
    }
    while (!pending.empty()) {
        // 先进先出保证当前层先于下一层处理。
        int vertex = pending.front(); pending.pop();
        for (int next : graph[vertex]) {
            // 第一次发现就是无权图最短路，不再重复覆盖。
            if (result.distance[next] != -1) continue;
            // 每走一条边，距离增加 1。
            result.distance[next] = result.distance[vertex] + 1;
            // 记住首次抵达的前驱，之后可逆向还原路径。
            result.parent[next] = vertex;
            pending.push(next);
        }
    }
    return result;
}

templates.example:
// 最小调用示例：下列断言同时展示正常结果与边界约定。
int main() {
    vector<vector<int>> graph = {{1}, {2}, {}, {2}, {}};
    auto result = bfs(graph, {0,3,0});
    assert(result.distance == vector<int>({0,1,1,0,-1}));
}

