// indegree[v] 是尚未删除的入边数，ready 存入度为 0 的点，order 是拓扑顺序。有重边就分别计数。返回 nullopt 表示有环，否则返回完整顺序（顺序可能不唯一）。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

optional<vector<int>> topological_sort(const vector<vector<int>>& graph) {
    int n = graph.size();
    vector<int> indegree(n, 0), order;
    // 先统计每个点全部入边，不能漏掉重复边。
    for (const auto& edges : graph) for (int next : edges) ++indegree[next];
    queue<int> ready;
    // 没有前置依赖的点可首先处理。
    for (int v=0; v<n; ++v) if (indegree[v] == 0) ready.push(v);
    while (!ready.empty()) {
        // 取出一个当前可处理的点，追加到结果。
        int vertex = ready.front(); ready.pop(); order.push_back(vertex);
        // 删除 vertex 的出边；某点最后一条入边被删掉时入队。
        for (int next : graph[vertex]) if (--indegree[next] == 0) ready.push(next);
    }
    // 还有点无法被删去，意味着余下子图中存在环。
    if ((int)order.size() != n) return nullopt;
    return order;
}

