// 外部下标从 0 开始，内部 tree 从 1 开始。tree[i] 管辖长度 lowbit(i) 的一段区间；add 单点加，prefix_sum(end) 求 [0,end)，range_sum(left,right) 求左闭右开区间。kth 仅适用于每个位置计数非负的频率数组。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> tree;
    explicit Fenwick(int n) : n(n), tree(n+1,0) {}
    void add(int index, long long delta) {
        assert(0 <= index && index < n);
        // 转成内部下标后，每次加 lowbit，更新所有包含该点的区间。
        for (++index; index<=n; index+=index&-index) tree[index] += delta;
    }
    // [0,end)
    long long prefix_sum(int end) const {
        assert(0 <= end && end <= n);
        long long sum = 0;
        // 每次减 lowbit，依次拆掉前缀最右的一段，区间互不重叠。
        for (; end>0; end-=end&-end) sum += tree[end];
        return sum;
    }
    long long range_sum(int left,int right) const {
        assert(0 <= left && left <= right && right <= n);
        // 右前缀减左前缀，得到 [left,right)。
        return prefix_sum(right)-prefix_sum(left);
    }
    // 各位置计数非负时，返回第 k 个元素的位置；不存在返回 n。
    int kth(long long k) const {
        // k 从 1 开始，非正数视为无效，统一返回 n。
        if (k <= 0) return n;
        int index = 0, step = 1;
        // 找到不超过 n 的最大 2 的幂，用来从高位试探。
        while (step <= n/2) step <<= 1;
        for (; step>0; step>>=1) {
            // 尝试跳过下一整块；tree[next] 恰是这块的计数。
            int next = index+step;
            // 若整块数量小于 k，答案还在后面，扣掉这一块继续找。
            if (next <= n && tree[next] < k) { index=next; k-=tree[next]; }
        }
        // index 是已跳过的位置数，也就是答案的外部 0 下标；超总数时返回 n。
        return index; // 已跳过 index 个位置，即答案的 0 下标。
    }
};

