    vector<long long> tr;
    explicit BIT(int n) : n(n), tr(n+1,0) {}
    void add(int idx, long long x) {
        assert(0 <= idx && idx < n);
        for (++idx; idx<=n; idx+=idx&-idx) tr[idx] += x;
    }

    long long sum(int r) const {
        assert(0 <= r && r <= n);
        long long sum = 0;
        for (; r>0; r-=r&-r) sum += tr[r];
        return sum;
    }
