        int idx = 0, pw = 1;
        while (pw <= n/2) pw <<= 1;
        for (; pw>0; pw>>=1) {
            int nv = idx+pw;
            if (nv <= n && tr[nv] < k) { idx=nv; k-=tr[nv]; }
        }
        return idx; 
    }
};

