using namespace std;

struct Seg {
    int n;
    vector<long long> sum, lazy;
    explicit Seg(const vector<long long>& a) : n(a.size()),
        sum(4*max(1,n),0), lazy(4*max(1,n),0) { if (n) build(1,0,n,a); }
    void build(int u,int l,int r,const vector<long long>& a) {
        if (r-l == 1) { sum[u]=a[l]; return; }
        int mid=l+(r-l)/2;
        build(u*2,l,mid,a); build(u*2+1,mid,r,a);
        pull(u);
    }
    void pull(int u) { sum[u]=sum[u*2]+sum[u*2+1]; }
    void apply(int u,int len,long long x) {
        sum[u]+=x*len; lazy[u]+=x;
    }
    void push(int u,int l,int mid,int r) {
        apply(u*2,mid-l,lazy[u]);
        apply(u*2+1,r-mid,lazy[u]); lazy[u]=0;
    }
    void update(int u,int l,int r,int ql,int qr,long long x) {
        if (qr<=l || r<=ql) return;
        if (ql<=l && r<=qr) { apply(u,r-l,x); return; }
        int mid=l+(r-l)/2; push(u,l,mid,r);
        update(u*2,l,mid,ql,qr,x);
        update(u*2+1,mid,r,ql,qr,x); pull(u);
    }
    long long query(int u,int l,int r,int ql,int qr) {
        if (qr<=l || r<=ql) return 0;
        if (ql<=l && r<=qr) return sum[u];
        int mid=l+(r-l)/2; push(u,l,mid,r);
        return query(u*2,l,mid,ql,qr)+query(u*2+1,mid,r,ql,qr);
    }
    void add(int l,int r,long long x) {
        assert(0<=l && l<=r && r<=n);
        if (l<r) update(1,0,n,l,r,x);
    }
    long long ask(int l,int r) {
        assert(0<=l && l<=r && r<=n);
        return l==r ? 0 : query(1,0,n,l,r);
    }
};

