// values 保存所有收集坐标，排序去重后就是“压缩下标→原值”的表。lower(x) 返回第一个 >=x 的位置，upper(x) 返回第一个 >x 的位置，允许返回 size()。index(x) 仅用于已收集值；original(i) 取回原值。压缩保持顺序与相等关系，不保持数值距离。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

template<class T> struct Compression {
    vector<T> values;
    explicit Compression(vector<T> input) : values(move(input)) {
        // 先排序，让相同值相邻，并使下标顺序等同于数值顺序。
        sort(values.begin(),values.end());
        // unique 把不同值移到前面，erase 真正删去重复尾部。
        values.erase(unique(values.begin(),values.end()),values.end());
    }
    int lower(const T& value) const {
        // 小于 value 的不同坐标数量，也就是第一个 >=value 的位置。
        return lower_bound(values.begin(),values.end(),value)-values.begin();
    }
    int upper(const T& value) const {
        // 小于等于 value 的不同坐标数量，也就是第一个 >value 的位置。
        return upper_bound(values.begin(),values.end(),value)-values.begin();
    }
    int index(const T& value) const { // 必须已收集该原值
        // 先找插入位置，再确认它确实是原先收集的值。
        int position=lower(value);
        // 防止把未收集的值误当作已有坐标使用。
        assert(position<(int)values.size() && values[position]==value);
        return position;
    }
    // 查询原始值用 at 检查下标；计算真实线段长度时必须还原坐标。
    const T& original(int index) const { return values.at(index); }
    int size() const { return values.size(); }
};

templates.example:
// 最小调用示例：下列断言同时展示正常结果与边界约定。
int main() {
    Compression<long long> coordinates({1000000000, -3, 7, -3});
    assert(coordinates.size()==3 && coordinates.index(7)==1);
    assert(coordinates.lower(0)==1 && coordinates.original(2)==1000000000);
}

