// PrefixSum.prefix[i] 是原数组 [0,i) 的和，故长度比原数组多 1。Difference.difference[i] 表示从 i 开始新增的增量；右端额外一格用于取消影响。所有区间统一左闭右开；差分先批量更新，再一次还原，不支持在未还原时直接查询区间和。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct PrefixSum {
    vector<long long> prefix;
    explicit PrefixSum(const vector<long long>& values) : prefix(values.size()+1,0) {
        // 前 i 个数之和再加第 i 个，得到前 i+1 个数之和。
        for (int i=0; i<(int)values.size(); ++i) prefix[i+1]=prefix[i]+values[i];
    }
    long long query(int left,int right) const {
        assert(0<=left && left<=right && right<(int)prefix.size());
        // 右前缀减左前缀，空区间也自然得到 0。
        return prefix[right]-prefix[left];
    }
};
struct Difference {
    vector<long long> difference;
    explicit Difference(int n) : difference(n+1,0) {}
    void add(int left,int right,long long delta) { // [left,right)
        assert(0<=left && left<=right && right<(int)difference.size());
        // 左端开始增加 delta，右端停止增加，区间外增量相互抵消。
        difference[left]+=delta; difference[right]-=delta;
    }
    vector<long long> materialize() const {
        // 最后一个差分槽只作哨兵，不属于原数组。
        vector<long long> result(difference.size()-1);
        // current 是扫描到当前位置时仍有效的所有增量之和。
        long long current=0;
        // 逐点累加差分，即可得到每个位置的最终增量。
        for (int i=0; i<(int)result.size(); ++i) result[i]=(current+=difference[i]);
        return result;
    }
};

