// 查找域是 [left,right)，谓词 feasible 必须先 false 后 true；返回第一个 true 的位置，若全 false 则返回传入的右边界。循环维持答案仍位于闭合的候选范围 [left,right]，其中 right 也可能只是“未找到”哨兵，不必调用谓词。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

template<class Predicate>
long long first_true(long long left,long long right,Predicate feasible) {
    // 允许空范围，此时直接返回左/右边界。
    assert(left<=right); // [left,right) 内 false 在前、true 在后。
    while (left<right) {
        // 先转 __int128 再做减法，即使两端接近 long long 极值也不溢出。
        long long middle=(long long)((__int128)left+((__int128)right-left)/2);
        // mid 已满足条件，答案不在它右侧，保留 mid。
        if (feasible(middle)) right=middle;
        // mid 不满足，连同左半段一起排除。
        else left=middle+1;
    }
    // 两端重合就是第一个满足条件的位置，或原 right 哨兵。
    return left;
}

