// z[i] 是 text[i..] 与整串前缀的最长公共前缀长度，这里约定 z[0]=n。已知匹配框 [left,right) 满足 text[left..right) == text[0..right-left)，right 只向右移动，所以总比较次数 O(n)。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<int> z_function(const string& text) {
    int n=text.size(); vector<int> z(n,0);
    // 明确首项约定；空串返回空数组。
    if (n) z[0]=n;
    for (int i=1,left=0,right=0; i<n; ++i) { // 已知区间 [left,right)
        // i 在匹配框内，可借用对应前缀位置 z[i-left]，但先截到框的右边界。
        if (i<right) z[i]=min(right-i,z[i-left]);
        // 框外还不知道的字符逐个比较；同时检查文本右边界。
        while (i+z[i]<n && text[z[i]]==text[i+z[i]]) ++z[i];
        // 只有新的匹配伸得更远时才更新匹配框。
        if (i+z[i]>right) {left=i; right=i+z[i];}
    }
    return z;
}

