// MOD 必须为素数；组合数预处理 limit<MOD。factorial[i]=i! mod MOD，inverse_factorial[i]=(i!)^-1 mod MOD。逆元只接受非零剩余类；n 超出预处理范围前应扩大预处理。快速幂乘法用 __int128 防止中间溢出。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

constexpr long long MOD=1000000007; // 必须为素数，且 MOD>1。
long long modular_power(long long base,long long exponent) {
    assert(exponent>=0);
    // 把负数也规范到 [0,MOD)。result 是已处理二进制位的乘积。
    base=(base%MOD+MOD)%MOD; long long result=1;
    while (exponent>0) {
        // 当前位为 1 时把对应幂乘入答案。
        if (exponent&1) result=(__int128)result*base%MOD;
        // 每轮平方得到下一位对应的幂，再右移指数。
        base=(__int128)base*base%MOD; exponent>>=1;
    }
    return result;
}
long long modular_inverse(long long value) {
    // 素数模下非零元素才存在乘法逆元。
    value=(value%MOD+MOD)%MOD; assert(value!=0);
    // 费马小定理：a^(MOD-2) 是 a 的逆元。
    return modular_power(value,MOD-2);
}
struct Combinations {
    vector<long long> factorial,inverse_factorial;
    explicit Combinations(int limit) : factorial(limit+1,1),inverse_factorial(limit+1,1) {
        assert(limit>=0 && limit<MOD);
        // 从小到大累计阶乘。
        for (int i=1; i<=limit; ++i) factorial[i]=factorial[i-1]*i%MOD;
        // 只对最高阶乘做一次快速幂求逆。
        inverse_factorial[limit]=modular_inverse(factorial[limit]);
        // 利用 (i-1)! 的逆元 = i × i! 的逆元，倒序线性递推。
        for (int i=limit; i>0; --i) inverse_factorial[i-1]=inverse_factorial[i]*i%MOD;
    }
    long long choose(int n,int k) const {
        // 越界的组合意义直接返回 0，不访问负下标。
        if (n<0 || k<0 || k>n) return 0;
        assert(n<(int)factorial.size());
        // C(n,k)=n!/(k!(n-k)!)，除法换成乘逆元。
        return factorial[n]*inverse_factorial[k]%MOD*inverse_factorial[n-k]%MOD;
    }
};

templates.example:
// 最小调用示例：下列断言同时展示正常结果与边界约定。
int main() {
    Combinations combinations(10); assert(combinations.choose(5,2)==10);
    assert(combinations.choose(5,6)==0 && modular_power(-2,3)==MOD-8);
    assert(2*modular_inverse(2)%MOD==1);
}

