// smallest_prime[x] 是 x 的最小质因子；初始 0 表示尚未被筛到。primes 按升序保存素数。每个合数仅由自己的最小质因子筛一次。factorize 返回（素因子，指数）对，1 的分解为空；只支持不超过预处理 limit 的正整数。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct LinearSieve {
    vector<int> primes, smallest_prime;
    explicit LinearSieve(int limit) : smallest_prime(limit+1,0) {
        assert(limit>=0);
        for (int value=2; value<=limit; ++value) {
            // 此前没被更小素数筛到，value 是素数，最小质因子就是自己。
            if (!smallest_prime[value]) {smallest_prime[value]=value; primes.push_back(value);}
            for (int prime : primes) {
                // 只枚举不大于 value 最小质因子的 prime，保证合数只被生成一次；乘积先提升到 long long。
                if (prime>smallest_prime[value] || 1LL*value*prime>limit) break;
                // 此时 prime 正是这个合数的最小质因子。
                smallest_prime[value*prime]=prime;
            }
        }
    }
    bool is_prime(int value) const {
        // 先判断范围，0、1 不是素数，数组内自身等于最小质因子才是素数。
        return 2<=value && value<(int)smallest_prime.size() && smallest_prime[value]==value;
    }
    vector<pair<int,int>> factorize(int value) const {
        assert(1<=value && value<(int)smallest_prime.size());
        vector<pair<int,int>> factors;
        while (value>1) {
            // 每轮取当前剩余数的最小质因子，并统计指数。
            int prime=smallest_prime[value],exponent=0;
            // 连续除尽该质因子，再处理下一个不同的素因子。
            do {value/=prime; ++exponent;} while (value%prime==0);
            // 输出一个完整的素因子及其次数。
            factors.push_back({prime,exponent});
        }
        return factors;
    }
};

