// 输入 a,b 非负；Bezout.gcd=gcd(a,b)，x,y 满足 a*x+b*y=gcd。系数用 __int128 保存中间乘积。inverse_mod 支持任意 modulus>1，只在 gcd(value,modulus)=1 时存在逆元，返回值规范到 [0,modulus)。
// 讲解版与竞赛版算法、边界及返回值完全一致；编号和区间约定见说明。
#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct Bezout { long long gcd; __int128 x,y; };
Bezout extended_gcd(long long a,long long b) {
    assert(a>=0 && b>=0);
    // 递归终点 a*1+0*0=a；a=b=0 也满足所给系数。
    if (b==0) return {a,1,0};
    // 先求 b*x'+(a%b)*y'=gcd，再回代到原来的 a,b。
    auto next=extended_gcd(b,a%b);
    // 由 a%b=a-(a/b)*b 得 x=y'，y=x'-(a/b)*y'。
    return {next.gcd,next.y,next.x-(__int128)(a/b)*next.y};
}
optional<long long> inverse_mod(long long value,long long modulus) {
    assert(modulus>1);
    // 先把负 value 规范成同余的非负剩余类。
    value%=modulus; if (value<0) value+=modulus;
    auto result=extended_gcd(value,modulus);
    // 不互质就不存在乘法逆元，不可随意取系数当逆元。
    if (result.gcd!=1) return nullopt;
    // 互质时 x 就是逆元；取模并修正负数，得到唯一规范代表。
    __int128 inverse=result.x%modulus;
    if (inverse<0) inverse+=modulus;
    return (long long)inverse;
}

