#include <cassert>
using namespace std;

constexpr long long NINF=numeric_limits<long long>::lowest()/4;
struct Item { int w; long long v; };
vector<long long> knapsack(int cap,const vector<Item>& it,
                           bool unlim=false,bool exact=false) {
    assert(cap>=0);
    vector<long long> dp(cap+1,exact ? NINF : 0);
    dp[0]=0;
    for (auto e : it) {
        assert(e.w>0); 
        auto upd=[&](int j) {
            if (dp[j-e.w]!=NINF)
                dp[j]=max(dp[j],dp[j-e.w]+e.v);
        };
        if (unlim) for (int j=e.w; j<=cap; ++j) upd(j);
        else for (int j=cap; j>=e.w; --j) upd(j);
    }
    return dp;
}

