#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<int> lis(const vector<long long>& a,bool strict=true) {
    vector<long long> d;
    vector<int> pos,p(a.size(),-1);
    for (int i=0; i<(int)a.size(); ++i) {
        int k=(strict ? lower_bound(d.begin(),d.end(),a[i])
                           : upper_bound(d.begin(),d.end(),a[i]))-d.begin();
        if (k>0) p[i]=pos[k-1];
        if (k==(int)d.size()) {d.push_back(a[i]); pos.push_back(i);}
        else {d[k]=a[i]; pos[k]=i;}
    }
    vector<int> ans;
    for (int i=pos.empty() ? -1 : pos.back(); i!=-1; i=p[i]) ans.push_back(i);
    reverse(ans.begin(),ans.end());
    return ans;
}

